import unittest

from solucao import distancia_entre
from solucao import letra_seguinte


class TestALetraEUmNumero(unittest.TestCase):
    def test_fileira_seguinte_maiscula(self):
        """letra_seguinte devolve a fileira depois do A maisculo"""
        self.assertEqual(letra_seguinte("A"), "B")

    def test_fileira_seguinte_minuscula(self):
        """letra_seguinte devolve a fileira depois do y minusculo"""
        self.assertEqual(letra_seguinte("y"), "z")

    def test_distancia_para_frente(self):
        """distancia_entre conta as fileiras do a ate o d"""
        self.assertEqual(distancia_entre("a", "d"), 3)

    def test_distancia_para_tras(self):
        """distancia_entre devolve negativo quando o fim vem antes"""
        self.assertEqual(distancia_entre("d", "a"), -3)

